import hashlib,json,re,sys
from pathlib import Path
base=Path('.temp/TASK-261017-sxydvh')
jobs=json.loads((base/'local-jobs.json').read_text())
results=[];missing=[];bad=[]
for job in jobs:
 p=base/(job['name']+'-result.json')
 if not p.exists():missing.append(job['name']);continue
 r=json.loads(p.read_text());assert r['args']==job['args'],('command changed',job['name']);results.append(r)
 if r.get('log_sha256'):assert hashlib.sha256((base/(job['name']+'.jsonl')).read_bytes()).hexdigest()==r['log_sha256'],job['name']
 if r.get('candidate'):assert r['candidate']==json.loads((base/'candidate-identity.json').read_text())['candidate'],job['name']
 if r['exit']!=0 or not r.get('environment','').startswith('isolated-v2'):bad.append((job['name'],r['exit'],r.get('environment')))
if missing or bad:
 print(json.dumps({'missing':missing,'bad':bad}));sys.exit(1)
terminals={};packages=set();failures=[];count=0
with (base/'local-full.jsonl').open('w') as merged:
 for job in jobs:
  observed=set()
  for line in (base/(job['name']+'.jsonl')).open():
   merged.write(line)
   try:r=json.loads(line)
   except ValueError:continue
   count+=1
   if r.get('Action')=='fail':failures.append((r.get('Package'),r.get('Test')))
   if 'Package'in r:packages.add(r['Package'])
   if 'Test'in r and '/'not in r['Test'] and r.get('Action')in ('pass','skip'):
    observed.add(r['Test']);terminals[(r['Package'],r['Test'])]=r['Action']
  args=job['args']
  if '-run'in args:
   mask=args[args.index('-run')+1]
   expected=mask.removeprefix('^(').removesuffix(')$').split('|') if mask.startswith('^(') else [mask.strip('^$')]
   if set(expected)-observed:raise AssertionError((job['name'],'missing test terminals',set(expected)-observed))
inventory={};pending=[]
for line in (base/'final-test-inventory.log').read_text().splitlines():
 if line.startswith('Test'):
  pending.append(line.strip())
 elif line.startswith('ok\t') or line.startswith('ok  \t'):
  fields=line.split();pkg=fields[1]
  inventory[pkg]=set(pending);pending=[]
 elif line.startswith('?'):
  pending=[]
assert not pending,pending
missing_inventory={(pkg,name)for pkg,names in inventory.items()for name in names} - set(terminals)
assert not missing_inventory,sorted(missing_inventory)
allpkgs=set((base/'local-packages.txt').read_text().splitlines())
assert allpkgs==packages,(allpkgs-packages,packages-allpkgs)
assert not failures,failures
summary={'candidate':json.loads((base/'candidate-identity.json').read_text()),'jobs':results,'package_count':len(packages),'top_level_test_count':len(terminals),'top_level_pass':sum(x=='pass'for x in terminals.values()),'top_level_skip':sum(x=='skip'for x in terminals.values()),'json_event_count':count,'failures':failures,'exact_masks_observed':True,'independent_inventory_covered':True,'inventory_test_count':sum(map(len,inventory.values()))}
(base/'local-full-summary.json').write_text(json.dumps(summary,indent=2))
print(json.dumps({k:v for k,v in summary.items() if k not in ('candidate','jobs')}))

